// Google Sheets -> Ziffr (spec 0043): the rows read from Google Sheets become the items a Feed sends. Each row names a Metric by its
// slug (as Ziffr shows it in the Metric's address), gives a number, and may give the period's first day (YYYY-MM-DD);
// a row without a period is the current period. Nothing else leaves: no other column is sent.
const SLUG = /^[a-z0-9][a-z0-9-]{0,99}$/;
const DAY = /^\d{4}-\d{2}-\d{2}$/;
const NUMBER = /^-?\d+(\.\d+)?$/;
const MAX_ITEMS = 500;
const items = [];
const skipped = [];
const seen = new Set();
let row = 1;
for (const item of $input.all()) {
  row++;
  const r = item.json;
  const metric = String(r.metric ?? '').trim();
  const raw = typeof r.value === 'number' ? String(r.value) : String(r.value ?? '').trim();
  const period = String(r.period ?? '').trim();
  if (metric === '' && raw === '' && period === '') continue;
  if (!SLUG.test(metric)) { skipped.push({ row, why: 'the metric is not a Metric slug' }); continue; }
  if (!NUMBER.test(raw)) { skipped.push({ row, metric, why: 'the value is not a plain number' }); continue; }
  if (period !== '' && !DAY.test(period)) { skipped.push({ row, metric, why: 'the period is not a day written YYYY-MM-DD' }); continue; }
  const at = metric + '/' + period;
  if (seen.has(at)) { skipped.push({ row, metric, why: 'the same Metric and period appear twice' }); continue; }
  seen.add(at);
  if (items.length >= MAX_ITEMS) { skipped.push({ row, metric, why: 'more than ' + MAX_ITEMS + ' rows' }); continue; }
  items.push(period === '' ? { metric, value: Number(raw) } : { metric, period, value: Number(raw) });
}
if (items.length === 0) throw new Error('No row holds a Metric slug and a number: the columns are metric, value and, if you like, period.');
// One run sends once, also when n8n retries it: the same rows give the same key, other rows another.
let h = 5381;
const body = JSON.stringify(items);
for (let i = 0; i < body.length; i++) h = ((h * 33) ^ body.charCodeAt(i)) >>> 0;
const key = 'sheets-' + new Date().toISOString().slice(0, 10) + '-' + h.toString(36) + '-' + items.length;
return [{ json: { items, skipped, key } }];

// Ziffr's answer to a batch of values (spec 0043): one result per item, in the order sent. A refused item fails the run,
// so that n8n shows it as failed and its owner looks; the rest were recorded all the same (each item stands on its own).
const results = Array.isArray($input.first().json.results) ? $input.first().json.results : [];
const shaped = $('Shape values').first().json;
const refused = results.filter((r) => r.status === 'refused');
if (refused.length) {
  const why = refused.slice(0, 10).map((r) => String(r.metric) + ' ' + String(r.period ?? '') + ' (' + String(r.code ?? 'refused') + '): ' + String(r.detail)).join('; ');
  throw new Error('Ziffr refused ' + refused.length + ' of ' + results.length + ' values: ' + why + (refused.length > 10 ? '; and more' : ''));
}
const count = (s) => results.filter((r) => r.status === s).length;
return [{ json: { recorded: count('recorded'), waitingForApproval: count('awaiting_approval'), proposedAsCorrection: count('locked'), skippedRows: shaped.skipped } }];
